        + p(_t("За победу: монеты (втрое больше обычного тайника), {0} и трофей — счётчик побед над каждым видом хранится в зале трофеев.", [RareHunt.reward(1).res.map(([k, n]) => `${esc(Bestiary.RESOURCES[k].name)} ×${n}`).join(', ')]))
        + `<h4 class="wk-fam">${_t("События недели")}</h4>`
